import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.RQXGjTIX.js";const g=JSON.parse('{"title":"与 AE2 原生设备互通","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interop.md","filePath":"guide/interop.md"}'),d={name:"guide/interop.md"};function i(l,t,n,s,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="与-ae2-原生设备互通" tabindex="-1">与 AE2 原生设备互通 <a class="header-anchor" href="#与-ae2-原生设备互通" aria-label="Permalink to &quot;与 AE2 原生设备互通&quot;">​</a></h1><p>本模组不添加新的总线、线缆或终端。它注册 AE2 的行为策略，并给原版 ME 接口补上气体能力， 于是 <strong>AE2 原生设备直接获得气体能力</strong>：</p><table tabindex="0"><thead><tr><th>AE2 原生设备</th><th>与 CCB 交互方式</th><th>本模组提供的钩子</th></tr></thead><tbody><tr><td><strong>输入总线</strong></td><td>从相邻气体储罐 / 机器抽取气体进入网络</td><td><code>StackImportStrategy</code> + 气体压力卡</td></tr><tr><td><strong>输出总线</strong></td><td>把网络里的气体压入相邻储罐 / 机器</td><td><code>StackExportStrategy</code> + 气体压力卡</td></tr><tr><td><strong>存储总线</strong></td><td>把相邻气体储罐当作 ME 存储（可读写）</td><td><code>ExternalStorageStrategy</code></td></tr><tr><td><strong>样板供应器</strong></td><td>把样板产物中的气体推入相邻机器；从网络取气作为原料</td><td><code>ExternalStorageStrategy</code>（AE2 的 <code>PatternProviderTargetCache</code> 使用它）</td></tr><tr><td><strong>ME 接口</strong></td><td>原版 <code>ae2:interface</code> 的槽位以固定 100 kPa 容器暴露给 CCB 管道，管道可直接抽气</td><td><code>AeInterfaceGasCompat</code></td></tr><tr><td><strong>终端 / 合成 / 自动合成</strong></td><td>气体作为一等资源参与存储、排序、合成请求</td><td><code>AEKeyType</code> + 存储元件</td></tr></tbody></table><h2 id="总线上的气体压力卡" tabindex="-1">总线上的气体压力卡 <a class="header-anchor" href="#总线上的气体压力卡" aria-label="Permalink to &quot;总线上的气体压力卡&quot;">​</a></h2><p>在 <strong>输入总线 / 输出总线</strong> 中安装 <code>gas_pressure_card</code> 后，可以为该总线设置气体目标压力：</p><ul><li>输出总线只输出到目标压力；</li><li>输入总线只在外部压力高于目标压力时抽取；</li><li>右键循环预设，潜行右键回退。</li></ul><h2 id="样板与-jei" tabindex="-1">样板与 JEI <a class="header-anchor" href="#样板与-jei" aria-label="Permalink to &quot;样板与 JEI&quot;">​</a></h2><ul><li>AE2 处理样板可以写气体输入/输出，样板供应器会自动从网络取气或把气体推入目标机器；</li><li>安装 <strong>AE2-JEI-Integration</strong> 后，在 JEI 里对带 CCB 气体的处理配方点击 <strong>+</strong>，可把气体输入/输出写进处理样板；</li><li>标准 AE2 样板只保存气体类型与数量，<strong>不保存目标压力</strong>；压力仍由机器/容器决定。</li></ul><h2 id="典型工厂布局" tabindex="-1">典型工厂布局 <a class="header-anchor" href="#典型工厂布局" aria-label="Permalink to &quot;典型工厂布局&quot;">​</a></h2><ol><li><strong>锅炉蒸汽</strong> → 管路 → ME 气体接口（导入模式）→ 网络；</li><li>网络里的气体 → 输出总线 + 气体压力卡 → 远处的 CCB 机器；</li><li>自动合成：样板里写气体原料 / 产物，样板供应器会自动从网络取气或把气体推入目标机器；</li><li>需要跨越长距离时，用 <a href="/appliedcraftedenergistics/guide/p2p.html">气体 P2P 隧道</a> 替代长管路。</li></ol><h2 id="不需要的东西" tabindex="-1">不需要的东西 <a class="header-anchor" href="#不需要的东西" aria-label="Permalink to &quot;不需要的东西&quot;">​</a></h2><ul><li>不需要“气体总线”：物品总线在本模组存在时就是气体总线；</li><li>不需要“气体终端”：现有终端会显示气体条目；</li><li>不需要为原版 ME 接口单独配置：适配器会自动把其槽位暴露给相邻 CCB 管道。</li></ul><h2 id="兼容性说明" tabindex="-1">兼容性说明 <a class="header-anchor" href="#兼容性说明" aria-label="Permalink to &quot;兼容性说明&quot;">​</a></h2><p>本模组只依赖 AE2 的公开 API（<code>appeng.api.*</code>）与 CCB 的公开 API（<code>net.ty.createcraftedbeginning.api.*</code>）， 不向它们注入任何 mixin。已与 Applied Pneumatics 1.0.9 + PneumaticCraft 8.2.24 在同一整合包中启动验证。</p><div class="tip custom-block"><p class="custom-block-title">想看代码级细节</p><p>接触点实现、CCB 端点契约与 0.1.2 兼容性分析见 <a href="/appliedcraftedenergistics/guide/developer-interop.html">开发者：与 CCB 气体管网的交互</a>。</p></div>',15)])])}const u=e(d,[["render",i]]);export{g as __pageData,u as default};
